// spec: specs/events.md
// seed: tests/seed.client.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/client.json') });

const EVENT_URL = '/events/087e8dd0-3043-4e55-b182-c2b646c7b7f8';

test.describe('רכישת כרטיס לאירוע', () => {
  test('מסך רכישה: סדר האזורים כמו בפריים 6075-5139, "קניית כרטיס" בסוף התוכן ולא צמוד לתחתית @android @prod-safe #6a86f7bc4808', async ({ page }) => {
    // 1. לפתוח את האירוע, לחכות לכפתור "קניית כרטיס" ב-DOM
    await page.goto(EVENT_URL);
    const buy = page.getByRole('button', { name: 'קניית כרטיס' });
    await expect(buy).toBeAttached();

    await expect(page.getByRole('button', { name: 'חזרה' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'שיתוף האירוע' })).toBeVisible();
    await expect(page.getByText('QA 08.10 אירוע', { exact: true })).toBeVisible();
    await expect(page.getByText('20 בדצמבר 2026 · 20:00')).toBeVisible();
    await expect(page.getByText('תל אביב QA')).toBeVisible();
    await expect(page.getByText('בחרו סוג כרטיס והשלימו תשלום בצורה מאובטחת דרך SafePay.')).toBeVisible();

    // 2. בלי לגלול — "קניית כרטיס" לא ב-viewport
    await expect(buy).not.toBeInViewport();

    // 3. סדר הבלוקים לפי y
    const radioRegular = page.getByRole('radio', { name: 'QA רגיל, ₪5.50' });
    const radioVip = page.getByRole('radio', { name: 'QA VIP, ₪1,850' });
    const ordered = [
      page.getByText('QA 08.10 אירוע', { exact: true }),
      page.getByText('בחרו סוג כרטיס', { exact: true }),
      radioRegular,
      radioVip,
      page.getByText('כמות כרטיסים', { exact: true }),
      page.getByText('עד 6 כרטיסים ברכישה', { exact: true }),
      page.getByText('פרטי הקונה', { exact: true }),
      page.getByText('סיכום תשלום', { exact: true }),
      page.getByText('התשלום יעובד בצורה מאובטחת דרך SafePay.', { exact: true }),
      buy,
    ];
    const ys: number[] = [];
    for (const loc of ordered) {
      const box = await loc.boundingBox();
      expect(box).not.toBeNull();
      ys.push(box!.y);
    }
    // שני הרדיו באותה שורה (אותו y) — הם לא חייבים לעלות; בין שאר הבלוקים y עולה
    const strictlyIncreasing = [0, 1, 2, 4, 5, 6, 7, 8, 9].map((i) => ys[i]);
    for (let i = 1; i < strictlyIncreasing.length; i++) {
      expect(strictlyIncreasing[i]).toBeGreaterThan(strictlyIncreasing[i - 1]);
    }
    expect(ys[3]).toBeGreaterThan(ys[1]);
    expect(ys[3]).toBeLessThan(ys[4]);

    // ברירת מחדל: בדיוק רדיו אחד מסומן
    await expect(page.getByRole('radio', { checked: true })).toHaveCount(1);

    // 4. לגלול ל"קניית כרטיס"
    const note = page.getByText('התשלום יעובד בצורה מאובטחת דרך SafePay.', { exact: true });
    await buy.evaluate((el) => el.scrollIntoView({ block: 'end' }));
    await expect(buy).toBeInViewport();
    const noteBox = await note.boundingBox();
    const buyBox = await buy.boundingBox();
    expect(buyBox!.y).toBeGreaterThan(noteBox!.y + noteBox!.height - 1);
  });
});
